DO $$DECLARE d text;BEGIN SELECT pg_get_functiondef('public.biz_can(uuid,text)'::regprocedure) INTO d;EXECUTE replace(d,'role-xwbmhg3b','role-xwbmhg3b');END$$;
-- Private global readers are inaccessible to browser roles and never change caller claims.
DO $$DECLARE d text;BEGIN
SELECT pg_get_functiondef('public.biz_dashboard_read(integer,text,integer,uuid,uuid,text)'::regprocedure) INTO d;
d:=replace(d,'public.biz_dashboard_read(','private.biz_dashboard_global_read(');
d:=replace(d,'all_ok:=public.is_super_admin(a) OR public.biz_all_scope(a);dept_ok:=public.biz_can(a,''biz.view_dept'');self_ok:=public.biz_can(a,''biz.view_own'');','all_ok:=true;dept_ok:=false;self_ok:=false;');EXECUTE d;
SELECT pg_get_functiondef('public.biz_dashboard_data(integer,text,integer,uuid,uuid,text)'::regprocedure) INTO d;
d:=replace(d,'public.biz_dashboard_data(','private.biz_dashboard_global_data(');d:=replace(d,'public.biz_dashboard_read(','private.biz_dashboard_global_read(');EXECUTE d;
END$$;
REVOKE ALL ON FUNCTION private.biz_dashboard_global_read(integer,text,integer,uuid,uuid,text),private.biz_dashboard_global_data(integer,text,integer,uuid,uuid,text) FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION public.biz_dashboard_published(_year integer,_period_kind text DEFAULT 'year',_period integer DEFAULT 1) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$DECLARE r jsonb;groups_ jsonb;lo int;hi int;eval_hi int;BEGIN
IF NOT public.biz_can(auth.uid(),'biz.dashboard_public') THEN RAISE EXCEPTION 'Không có quyền xem Dashboard tổng hợp.';END IF;
r:=private.biz_dashboard_global_data(_year,_period_kind,_period,NULL,NULL,'official');lo:=(r->>'lo')::int;hi:=(r->>'hi')::int;eval_hi:=least(hi,(r->>'current_month')::int);
WITH nodes AS (SELECT 0::bigint ord,'block'::text level,'all'::text id,'Toàn Khối'::text name,r->'facts' facts UNION ALL SELECT row_number() OVER(ORDER BY (SELECT count(*) FROM public.biz_departments d WHERE d.system_id=s.id AND d.active) DESC,s.created_at,s.name),'system',s.id::text,s.name,coalesce((SELECT jsonb_agg(f) FROM jsonb_array_elements(r->'facts') f WHERE f->>'system_id'=s.id::text),'[]') FROM public.biz_systems s WHERE s.active)
SELECT jsonb_agg(jsonb_build_object('level',level,'id',id,'name',name,'metrics',public.biz_dashboard_aggregate(facts,lo,hi),'evaluation_metrics',public.biz_dashboard_aggregate(facts,lo,eval_hi)) ORDER BY ord) INTO groups_ FROM nodes;
RETURN jsonb_build_object('year',_year,'period_kind',_period_kind,'period',_period,'mode','official','lo',lo,'hi',hi,'evaluation_hi',eval_hi,'ongoing',eval_hi<hi,'groups',coalesce(groups_,'[]'),'server_now',now());END$$;
REVOKE ALL ON FUNCTION public.biz_dashboard_published(integer,text,integer) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.biz_dashboard_published(integer,text,integer) TO authenticated;
CREATE FUNCTION public.biz_exception_save(_data jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE id_ uuid:=nullif(_data->>'id','')::uuid;r public.biz_access_exceptions;BEGIN
IF auth.uid() IS NULL OR NOT (public.is_super_admin(auth.uid()) OR private.sig_can(auth.uid(),'settings.role')) THEN RAISE EXCEPTION 'Không có quyền quản lý ngoại lệ.';END IF;
PERFORM pg_advisory_xact_lock(hashtext('biz_org_structure'));
IF id_ IS NOT NULL THEN SELECT * INTO r FROM public.biz_access_exceptions WHERE id=id_ FOR UPDATE;IF r.id IS NULL OR r.revoked_at IS NOT NULL THEN RAISE EXCEPTION 'Không tìm thấy ngoại lệ đang áp dụng.';END IF;IF btrim(coalesce(_data->>'reason',''))='' THEN RAISE EXCEPTION 'Cần lý do thu hồi.';END IF;UPDATE public.biz_access_exceptions SET revoked_at=now() WHERE id=id_;
ELSE INSERT INTO public.biz_access_exceptions(user_id,role_id,permission,scope_kind,system_id,department_id,team_id,started_at,ended_at,granted_by,reason) VALUES(nullif(_data->>'user_id','')::uuid,nullif(_data->>'role_id',''),_data->>'permission',_data->>'scope_kind',nullif(_data->>'system_id','')::uuid,nullif(_data->>'department_id','')::uuid,nullif(_data->>'team_id','')::uuid,coalesce(nullif(_data->>'started_at','')::timestamptz,now()),nullif(_data->>'ended_at','')::timestamptz,auth.uid(),btrim(_data->>'reason')) RETURNING id INTO id_;END IF;
INSERT INTO public.biz_org_events(actor_id,action,payload) VALUES(auth.uid(),'access_exception',jsonb_build_object('id',id_,'old',to_jsonb(r),'new',_data));RETURN id_;END$$;
REVOKE ALL ON FUNCTION public.biz_exception_save(jsonb) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.biz_exception_save(jsonb) TO authenticated;
CREATE OR REPLACE FUNCTION public.biz_position_save(_data jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE id_ uuid:=nullif(_data->>'id','')::uuid;old_ jsonb;policy_ text:=coalesce(_data->>'business_policy',CASE WHEN _data->>'unit_kind'='individual' THEN 'personal' ELSE 'manager' END);all_ boolean:=coalesce((_data->>'all_business')::boolean,false);BEGIN
IF NOT public.biz_org_can_manage() THEN RAISE EXCEPTION 'Không có quyền quản lý chức vụ.';END IF;PERFORM pg_advisory_xact_lock(hashtext('biz_org_structure'));
IF all_ AND (policy_<>'executive' OR _data->>'unit_kind'<>'system') THEN RAISE EXCEPTION 'Phạm vi toàn Khối chỉ dành cho chức vụ giám sát điều hành.';END IF;
IF id_ IS NULL THEN INSERT INTO public.biz_positions(name,description,level,unit_kind,sort_order,active,business_policy,all_business) VALUES(btrim(_data->>'name'),coalesce(_data->>'description',''),coalesce((_data->>'level')::int,0),_data->>'unit_kind',coalesce((_data->>'sort_order')::int,0),coalesce((_data->>'active')::boolean,true),policy_,all_) RETURNING id INTO id_;
ELSE SELECT to_jsonb(p) INTO old_ FROM public.biz_positions p WHERE id=id_ FOR UPDATE;IF old_ IS NULL THEN RAISE EXCEPTION 'Không tìm thấy chức vụ.';END IF;UPDATE public.biz_positions SET name=btrim(_data->>'name'),description=coalesce(_data->>'description',''),level=coalesce((_data->>'level')::int,0),unit_kind=_data->>'unit_kind',sort_order=coalesce((_data->>'sort_order')::int,0),active=coalesce((_data->>'active')::boolean,true),business_policy=policy_,all_business=all_ WHERE id=id_;END IF;
INSERT INTO public.biz_org_events(actor_id,action,payload) VALUES(auth.uid(),'position',jsonb_build_object('id',id_,'old',old_,'new',_data));RETURN id_;END$$;
ALTER TABLE public.biz_access_exceptions ADD CONSTRAINT biz_exception_scope_target CHECK((scope_kind='all' AND permission='biz.view_all') OR (permission='biz.view_dept' AND ((scope_kind='system' AND system_id IS NOT NULL) OR (scope_kind='department' AND department_id IS NOT NULL) OR (scope_kind='team' AND team_id IS NOT NULL))) OR (scope_kind='all' AND permission IN ('biz.org_manage','biz.kr_manage','biz.deadline_manage','biz.workflow_manage','biz.dept_manage')));
-- Scoped read exceptions do not grant unscoped actions.
DO $$DECLARE d text;BEGIN SELECT pg_get_functiondef('public.biz_can(uuid,text)'::regprocedure) INTO d;d:=replace(d,'IF public.biz_exception_ok(_actor,_permission) THEN RETURN true;END IF;','IF public.biz_exception_ok(_actor,_permission) THEN RETURN true;END IF;');EXECUTE d;END$$;
